body.css:
/* Glass's material: everything drawn is made of these names, and nothing
   else. Colours come in a light and a dark. Type is set as the rule's
   surface sets it by default: the prose in a sans, the headings in a serif
   that grows over it by a ratio of 1.45, a line of 600px, spaced at 1.45 of
   the serif's size. Each face is sized to the serif's x-height, so the sans
   reads as large as the serif would. No face is fetched: loading one would
   tell whoever serves it who reads, and when. */

:root {
  --ground: #fbfaf7;
  --raised: #ffffff;
  --ink: #23211d;
  --quiet: #6f6a61;
  --line: #e4e0d7;
  --accent: #3d5a80;
  --wash: rgb(0 0 0 / 0.035);
  --door: color-mix(in oklch, var(--accent) 45%, var(--ground));

  --serif: "Source Serif 4", "Iowan Old Style", Charter, "Palatino Linotype", Georgia, serif;
  --sans: "Source Sans 3", ui-sans-serif, system-ui, -apple-system, "Segoe UI", sans-serif;
  --mono: "Source Code Pro", ui-monospace, "SF Mono", Menlo, Consolas, monospace;

  /* The serif's size, which the lines and the headings are reckoned from,
     and the sans's, matched to it by x-height and lifted a step. */
  --base: 17px;
  --text: calc(var(--base) * 0.967);
  --ratio: 1.45;
  --leading: calc(var(--base) * 1.45);
  --leading-close: 1.5;
  --leading-tight: 1.2;
  --lead: 1.12em;
  --aside: 0.93em;
  --code: 0.8em;
  --title: calc(var(--base) * var(--ratio) * var(--ratio));
  --h2: calc(var(--base) * var(--ratio));
  --h3: calc(var(--base) * 1.204);
  --h4: var(--base);
  --heading: 1.1rem;
  --small: 0.875rem;
  --smaller: 0.75rem;
  --step: 12px;

  --measure: 600px;
  --gap: 1rem;
  --inset: 0.8em 1em;
  --radius: 8px;
  --pill: 99px;
  --hairline: 1px;
  --rule: 3px;
  --thin: 0;

  color-scheme: light dark;
}

@media (prefers-color-scheme: dark) {
  :root {
    --ground: #171614;
    --raised: #1e1d1a;
    --ink: #e8e4dc;
    --quiet: #9b958a;
    --line: #2f2c28;
    --accent: #9db4d6;
    --wash: rgb(255 255 255 / 0.05);
    /* Light on dark reads heavier than dark on light, so it is set a step thinner. */
    --thin: 30;
  }
}

body {
  margin: 0;
  background: var(--ground);
  color: var(--ink);
  font-family: var(--sans);
  font-size: var(--text);
  font-weight: calc(400 - var(--thin));
  line-height: var(--leading);
  -webkit-font-smoothing: antialiased;
}

/* Holding the measure, the page keeps its own gutters beside it. */
#glass {
  box-sizing: content-box;
}

#glass {
  max-width: var(--measure);
  min-height: 100dvh;
  margin: 0 auto;
  padding: 0 var(--gap);
}

/* A link reads in the ink, marked by a fine underline in the accent that
   deepens as it is pointed at, so a paragraph full of links stays a
   paragraph. */
a {
  color: inherit;
  text-decoration: underline;
  text-decoration-color: var(--door);
  text-decoration-thickness: 1px;
  text-underline-offset: 0.18em;
  transition: text-decoration-color 0.1s;
}

a:hover {
  text-decoration-color: var(--accent);
}

code,
pre {
  font-family: var(--mono);
}

h1,
h2,
h3,
h4,
h5,
h6 {
  font-family: var(--serif);
  font-weight: calc(600 - var(--thin));
}

/* Reading: a place drawn whole, its prose in a steady rhythm, each block a
   step below the last, its headings in the serif growing over it. */

.reader p,
.reader li {
  margin: 0 0 var(--step);
}

.reader li {
  margin-bottom: 8px;
}

.reader ul,
.reader ol {
  padding-left: 1.4rem;
  margin: 0 0 var(--step);
}

.reader li > ul,
.reader li > ol {
  margin: 8px 0 0;
}

.reader li::marker {
  color: var(--quiet);
}

.reader blockquote {
  margin: 0 0 var(--step);
  padding-left: 16px;
  border-left: 2px solid var(--line);
  color: var(--quiet);
}

.reader blockquote > :last-child {
  margin-bottom: 0;
}

.reader code {
  font-size: 0.92em;
}

.reader pre code {
  font-size: inherit;
}

.reader hr {
  border: 0;
  border-top: var(--hairline) solid var(--line);
  margin: calc(var(--step) * 2) 0;
}

.reader em {
  font-style: italic;
}

.reader strong {
  font-weight: calc(600 - var(--thin));
}

.reader section > :is(h2, h3, h4, h5, h6) {
  font-family: var(--serif);
  font-weight: calc(600 - var(--thin));
  line-height: var(--leading-tight);
  letter-spacing: -0.012em;
  margin: 1.6em 0 0.56em;
}

.reader section > h2 {
  font-size: var(--h2);
}

.reader section > h3 {
  font-size: var(--h3);
}

.reader section > :is(h4, h5, h6) {
  font-size: var(--h4);
}

.reader .section-link {
  color: inherit;
  text-decoration: none;
}

.reader .section-link:hover {
  color: var(--accent);
}

/* What is not prose, standing in a flow, keeps the flow's step. */
.reader > .slot,
.reader section > .slot {
  margin: 0 0 var(--step);
}

.glass-note {
  color: var(--quiet);
  font: var(--small) / var(--leading-close) var(--sans);
}

/* A place: what a mount draws whole. The way down to it stands above its
   title, quiet, in the sans. */

.place > nav {
  font: var(--small) / var(--leading-close) var(--sans);
  color: var(--quiet);
  margin-bottom: calc(var(--gap) * 2.5);
}

.place > nav a {
  color: inherit;
  text-decoration: none;
}

.place > nav a:hover {
  color: var(--ink);
}

.place > nav a + a::before {
  content: "›";
  margin: 0 0.5em;
  opacity: 0.6;
}

.place > h1 {
  font-family: var(--serif);
  font-size: var(--title);
  line-height: 1.12;
  font-weight: calc(600 - var(--thin));
  margin: 6px 0 0.56em;
  letter-spacing: -0.014em;
}

.place > h2 {
  font: var(--small) / var(--leading-close) var(--sans);
  text-transform: uppercase;
  letter-spacing: 0.06em;
  color: var(--quiet);
  margin: calc(var(--gap) * 2.5) 0 calc(var(--gap) * 0.75);
}

.place pre {
  background: var(--wash);
  border-radius: 10px;
  padding: 12px 16px;
  margin: 0 0 var(--step);
  overflow: auto;
  max-height: 32rem;
  font-size: var(--small);
  line-height: var(--leading-close);
}

/* What is said about a thing beside it, small and quiet. */

.meta {
  display: block;
  font: var(--smaller) / var(--leading-close) var(--sans);
  color: var(--quiet);
}

/* A card: what a face slot draws, entered by a press. The slot is what is
   pressed and focused, so it is the slot that marks the card. */

.card {
  display: block;
  padding: var(--gap) calc(var(--gap) * 1.15);
  border: var(--hairline) solid var(--line);
  border-radius: var(--radius);
  background: var(--raised);
  cursor: pointer;
  transition: border-color 0.15s;
}

.slot.face:hover > .card,
.slot.face:focus-visible > .card {
  border-color: var(--quiet);
}

.slot.face:focus-visible {
  outline: none;
}

.card .meta {
  margin-top: 0.5em;
}

/* A list: its items one under another. */

.list {
  list-style: none;
  padding: 0;
  margin: 0;
  display: grid;
  gap: calc(var(--gap) * 0.75);
}

/* A component made of data: its mounts one under another, set off by
   space. */

.template {
  padding: calc(var(--gap) * 3) 0 calc(var(--gap) * 6);
}

.template > .slot + .slot {
  margin-top: calc(var(--gap) * 2);
}

/* A grouping's collections, one under another, or side by side as cards
   where there is room. */

.collections {
  display: grid;
  gap: calc(var(--gap) * 0.75);
  margin: 0 0 calc(var(--gap) * 1.5);
}

.collections.cards {
  grid-template-columns: repeat(auto-fill, minmax(12rem, 1fr));
}

/* A collection standing open: its name, and the holons it holds named
   beneath it, set apart by spacing alone. */

.collection-open {
  padding: 0.4rem 0;
  cursor: pointer;
}

.collection-open > .meta {
  display: inline;
  margin-left: 0.6em;
}

.collection-open .members {
  display: flex;
  flex-wrap: wrap;
  align-items: baseline;
  gap: 0.15rem 0.9rem;
  margin-top: 0.35rem;
  font: var(--small) / var(--leading-close) var(--sans);
}

.collection-open .member {
  padding: 0;
  border: 0;
  background: none;
  color: var(--ink);
  font: inherit;
  cursor: pointer;
}

.collection-open .member:hover,
.collection-open .member:focus-visible {
  text-decoration: underline;
  outline: none;
}

/* A list's items as cards, side by side where there is room. */

.list.cards {
  grid-template-columns: repeat(auto-fill, minmax(14rem, 1fr));
}

/* A search: where one stands, its parts as chips beside what is typed,
   and what is found beneath. Above what it searches from, it stays at the
   top as the page moves, and shows what it found while it holds the
   focus; in a menu, always. */

.search {
  position: relative;
  font: var(--small) / var(--leading-close) var(--sans);
}

.template > .slot:first-child:has(> .search) {
  position: sticky;
  top: 0;
  z-index: 5;
  background: var(--ground);
  padding: 0.6rem 0;
  margin-top: calc(var(--gap) * -2);
}

.search-field {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 0.3rem;
  padding: 0.35rem 0.45rem;
  background: var(--raised);
  border: var(--hairline) solid var(--line);
  border-radius: var(--radius);
}

.search-field:focus-within {
  border-color: var(--quiet);
}

.search .part {
  display: inline-flex;
  align-items: center;
  gap: 0.15rem;
  padding: 0.15em 0.25em 0.15em 0.6em;
  border: 0;
  border-radius: var(--pill);
  background: var(--line);
  color: var(--ink);
  font: inherit;
  white-space: nowrap;
  max-width: 100%;
  min-width: 0;
}

/* A long name shortens to fit, so the part's × is always within reach. */
.search .part-change {
  min-width: 0;
}

.search .part-value {
  overflow: hidden;
  text-overflow: ellipsis;
}

.search button.part {
  padding-right: 0.6em;
  background: none;
  color: var(--quiet);
  cursor: pointer;
}

.search button.part:hover,
.search button.part:focus-visible {
  color: var(--ink);
  outline: none;
}

.search .part-change {
  display: inline-flex;
  gap: 0.3em;
  padding: 0;
  border: 0;
  background: none;
  color: inherit;
  font: inherit;
  cursor: pointer;
}

.search .part-change:disabled {
  cursor: default;
}

.search .part-field {
  color: var(--quiet);
}

.search .part-change:not(:disabled):hover .part-value,
.search .part-change:focus-visible .part-value {
  text-decoration: underline;
  outline: none;
}

.search .part.pending {
  padding-right: 0.6em;
  background: none;
  color: var(--accent);
  font-weight: 600;
}

.search .part.pending[hidden] {
  display: none;
}

.search .let-go {
  border: 0;
  background: none;
  color: var(--quiet);
  font: inherit;
  line-height: 1;
  padding: 0 0.3em;
  border-radius: var(--pill);
  cursor: pointer;
}

.search .let-go:hover,
.search .let-go:focus-visible {
  color: var(--ink);
  background: var(--ground);
  outline: none;
}

.search-input {
  flex: 1 1 10rem;
  min-width: 8rem;
  padding: 0.25em 0.2em;
  border: 0;
  background: none;
  color: var(--ink);
  font: inherit;
  outline: none;
}

.search-status {
  margin: 0.35rem 0 0;
  padding: 0 0.5rem;
  color: var(--quiet);
  font-size: var(--smaller);
}

.search-found {
  display: none;
  list-style: none;
  margin: 0.3rem 0 0;
  padding: 0.3rem;
  max-height: min(24rem, 60vh);
  overflow-y: auto;
  background: var(--raised);
  border: var(--hairline) solid var(--line);
  border-radius: var(--radius);
}

.search:focus-within .search-found:not(:empty),
.search.pressed .search-found:not(:empty) {
  display: block;
}

.slot:not(.menu *) > .search .search-found {
  position: absolute;
  left: 0;
  right: 0;
  box-shadow: 0 0.5rem 1.5rem rgb(0 0 0 / 0.12);
}

.found {
  display: flex;
  align-items: center;
  gap: 0.3rem;
  border-radius: calc(var(--radius) - 2px);
}

.found.active,
.found:hover {
  background: var(--ground);
}

.found .lead {
  flex: 1;
  display: flex;
  align-items: baseline;
  justify-content: space-between;
  gap: 1rem;
  min-width: 0;
  padding: 0.4rem 0.55rem;
  border: 0;
  background: none;
  color: var(--ink);
  font: inherit;
  text-align: left;
  cursor: pointer;
}

.found-said {
  display: block;
  padding: 0.4rem 0.55rem;
  color: var(--quiet);
}

.found-label {
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.found .meta {
  flex-shrink: 0;
  max-width: 50%;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

/* A mount's menu: the search, laid where the press landed. */

.menu {
  position: fixed;
  z-index: 10;
  width: min(30rem, calc(100vw - 16px));
  padding: 0.35rem;
  background: var(--ground);
  border: var(--hairline) solid var(--line);
  border-radius: var(--radius);
  box-shadow: 0 0.5rem 1.5rem rgb(0 0 0 / 0.18);
}
